'use strict';
let data,view='overview',days=14,weekStart,noteId;
let notes={};try{notes=JSON.parse(localStorage.getItem('momentum-notes')||'{}')}catch{}
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(n,d=0)=>Number(n).toLocaleString('de-DE',{maximumFractionDigits:d}),dt=s=>new Date(s+'T12:00:00Z'),iso=d=>d.toISOString().slice(0,10),add=(s,n)=>iso(new Date(dt(s).getTime()+n*864e5)),monday=s=>add(s,-((dt(s).getUTCDay()+6)%7)),short=s=>dt(s).toLocaleDateString('de-DE',{day:'2-digit',month:'2-digit',timeZone:'UTC'}),kind=a=>a.type.includes('strength')?'strength':'cardio';
const avg=values=>values.length?values.reduce((a,b)=>a+b,0)/values.length:null;
const due=()=>data.plan.filter(p=>p.date<=data.asOf),completed=p=>data.activities.some(a=>a.date===p.date&&kind(a)===p.type),inWeek=a=>a.date>=weekStart&&a.date<=add(weekStart,6);
function valid(d){if(d?.schemaVersion!==1||!/^\d{4}-\d{2}-\d{2}$/.test(d.asOf)||!['activities','recovery','weights','plan'].every(k=>Array.isArray(d[k])))throw Error('Unbekanntes Datenformat');for(const k of ['activities','recovery','weights','plan'])if(d[k].length>10000||d[k].some(r=>!/^\d{4}-\d{2}-\d{2}$/.test(r.date)))throw Error('Ungültige Datumswerte');if(d.activities.some(a=>typeof a.id!=='string'||typeof a.type!=='string'||!Number.isFinite(a.minutes)||!Array.isArray(a.sets)))throw Error('Ungültige Trainingsdaten');return d}
async function load(){data=valid(await(await fetch('data.json?t='+Date.now(),{cache:'no-store'})).json());weekStart=weekStart||monday(data.asOf);render()}
function metric(label,value,unit,foot){return `<div class="metric"><div class="metric-title">${label}</div><div class="metric-value">${value} <small>${unit}</small></div><div class="metric-foot">${foot}</div></div>`}
function render(){
 const acts=data.activities.filter(inWeek),plan=data.plan.filter(inWeek),elapsed=plan.filter(p=>p.date<=data.asOf),done=elapsed.filter(completed),rec=data.recovery.filter(inWeek),sleep=avg(rec.filter(r=>r.sleep!=null).map(r=>r.sleep));
 $('week-label').textContent=short(weekStart)+' – '+short(add(weekStart,6));
 const today=iso(new Date()),lag=Math.round((dt(today)-dt(data.asOf))/864e5);
 $('freshness').textContent='Daten bis '+short(data.asOf)+data.asOf.slice(0,4)+(lag>1?' · '+lag+' Tage alt':'');
 $('metrics').innerHTML=metric('Einheiten diese Woche',num(acts.length),' / '+plan.length,done.length+' von '+elapsed.length+' fälligen Terminen erledigt')+metric('Trainingszeit',num(acts.reduce((s,a)=>s+a.minutes,0)),'min','Kraft '+acts.filter(a=>kind(a)==='strength').length+' · Cardio '+acts.filter(a=>kind(a)==='cardio').length)+metric('Schlaf im Wochenschnitt',sleep==null?'—':`${Math.floor(sleep/60)}:${String(Math.round(sleep%60)).padStart(2,'0')}`,'h',rec.filter(r=>r.sleep!=null).length+' gemessene Nächte')+metric('Letztes Gewicht',data.weights.length?num(data.weights.at(-1).kg,2):'—','kg',data.weights.length?'Renpho · '+short(data.weights.at(-1).date):'Keine Messung');
 $('week-progress').textContent=done.length+' / '+elapsed.length+' fällig erledigt';
 $('week').innerHTML=Array.from({length:7},(_,i)=>{const date=add(weekStart,i),p=plan.find(p=>p.date===date),a=acts.find(a=>a.date===date),isDone=p&&completed(p);return `<div class="day ${p?p.type:'rest'} ${isDone?'done':''} ${date===data.asOf?'today':''}"><div class="day-label">${['MO','DI','MI','DO','FR','SA','SO'][i]}</div><div class="day-date">${dt(date).getUTCDate()}</div><div class="day-name">${p?`<span class="day-icon">${p.type==='strength'?'↗':'≈'}</span>${esc(p.name.replace(/ ·.*$/,''))}`:'Ruhetag'}</div><div class="day-state">${isDone?'✓ Erledigt · '+num(a?.minutes||0)+' min':p?(date>data.asOf?'Geplant':'Nicht erfasst'):'Erholen & auftanken'}</div></div>`}).join('');
 const allDue=due(),allDone=allDue.filter(completed),percentage=allDue.length?Math.round(allDone.length/allDue.length*100):null;
 $('momentum').innerHTML=`<div class="momentum-number">${percentage??'—'}<small>${percentage==null?'':'%'}</small></div><div class="momentum-label">${allDone.length} von ${allDue.length} fälligen Einheiten seit ${allDue.length?short(allDue[0].date):'Planstart'} erledigt</div>`;
 const weeks=[...new Set(allDue.map(p=>monday(p.date)))].slice(-6);
 $('momentum-bars').innerHTML=weeks.map(w=>{const ds=allDue.filter(p=>monday(p.date)===w),n=ds.filter(completed).length;return `<div class="momentum-bar"><div class="track" title="${n} von ${ds.length} erledigt"><div class="fill" style="height:${n/ds.length*100}%"></div></div>${short(w)} · ${n}/${ds.length}</div>`}).join('');
 const latest=data.recovery.at(-1),last=data.activities.at(-1),w=data.weights.at(-1);
 $('insights').innerHTML=`<div class="insight"><strong>Rhythmus: ${allDone.length}/${allDue.length} Termine erfüllt</strong><p>${percentage===100?'Du hast alle bisher fälligen Termine im geladenen Plan absolviert.':'Nicht erfasste Termine sind keine Niederlage. Prüfe, ob die Uhr synchronisiert ist.'}</p></div><div class="insight"><strong>${latest?.sleep<420?'Schlaf hat gerade Priorität':'Erholung im Blick'}</strong><p>${latest?`Letzte Nacht ${Math.floor(latest.sleep/60)} h ${latest.sleep%60} min · HRV ${latest.hrv??'—'} ms. ${latest.hrvStatus==='BALANCED'?'Garmin: ausgeglichen.':''} Einzelwerte sind keine Trainingsfreigabe.`:'Noch keine Erholungsdaten.'}</p></div><div class="insight"><strong>Fortschritt braucht Vergleichbarkeit</strong><p>Puls ohne Watt oder Tempo zeigt keine Leistungssteigerung. Maschinengewichte vergleichen wir nur bei gleicher Einstellung; 0-kg-Einträge sind kein bestätigtes Squat-Gewicht.</p></div>`;
 $('overview').hidden=view!=='overview';$('crumb').textContent={overview:'ÜBERBLICK',strength:'KRAFT',cardio:'AUSDAUER',recovery:'ERHOLUNG'}[view];$('title').textContent={overview:'Dein Momentum.',strength:'Stärker. Schritt für Schritt.',cardio:'Deine Ausdauer.',recovery:'Raum für Erholung.'}[view];$('subtitle').textContent={overview:'Ein Blick auf das, was du aufgebaut hast.',strength:'Wiederholungen, Lasten und vergleichbare Einheiten.',cardio:'Dranbleiben, Belastung verstehen, Ausdauer aufbauen.',recovery:'Schlaf, HRV und Ruhepuls im Zusammenhang.'}[view];
 document.querySelectorAll('.nav').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);b.setAttribute('aria-current',b.dataset.view===view?'page':'false')});
 renderChart();renderActivities();
}
const metrics={sleep:{label:'Schlafdauer',unit:'Stunden',color:'#8bbcc7'},hrv:{label:'HRV über Nacht',unit:'ms',color:'#b8cb9c'},restingHr:{label:'Ruhepuls',unit:'bpm',color:'#edaa69'},kg:{label:'Körpergewicht',unit:'kg',color:'#edaa69'},cardioHr:{label:'Ø Puls pro Cardio-Einheit',unit:'bpm',color:'#8bbcc7'},cardioMinutes:{label:'Cardio-Dauer',unit:'Minuten',color:'#8bbcc7'},load:{label:'Höchste erfasste Last',unit:'kg',color:'#edaa69'},reps:{label:'Erfasste Wiederholungen gesamt',unit:'Wdh.',color:'#b8cb9c'}};
function setChartChoices(){const keys=view==='strength'?['load','reps']:view==='cardio'?['cardioHr','cardioMinutes']:['sleep','hrv','restingHr','kg'];$('chart-metric').innerHTML=keys.map(k=>`<option value="${k}">${metrics[k].label}</option>`).join('');const names=[...new Set(data.activities.flatMap(a=>a.sets.map(s=>s.exercise_name)))].filter(n=>n&&n!=='UNKNOWN').sort();$('exercise').innerHTML=names.map(n=>`<option value="${esc(n)}">${esc(n.replaceAll('_',' ').toLowerCase())}</option>`).join('');const baseline=names.find(n=>n==='BARBELL_BENCH_PRESS');if(baseline)$('exercise').value=baseline;$('exercise').hidden=view!=='strength'}
function renderChart(){if(!$('chart-metric').options.length)setChartChoices();const key=$('chart-metric').value,metric=metrics[key],cutoff=add(data.asOf,-days+1);let pts=[];const exercise=$('exercise').value;
 if(['sleep','hrv','restingHr'].includes(key))pts=data.recovery.map(r=>({date:r.date,value:key==='sleep'?r.sleep/60:r[key]})).filter(p=>p.value!=null);
 else if(key==='kg')pts=data.weights.map(w=>({date:w.date,value:w.kg}));
 else if(key.startsWith('cardio'))pts=data.activities.filter(a=>kind(a)==='cardio').map(a=>({date:a.date,value:key==='cardioHr'?a.avgHr:a.minutes}));
 else pts=data.activities.map(a=>{const ss=a.sets.filter(s=>s.exercise_name===exercise&&s.reps>0);const loads=ss.map(s=>s.load_kg).filter(x=>Number.isFinite(x)&&x>0);return {date:a.date,value:key==='load'?(loads.length?Math.max(...loads):null):(ss.length?ss.reduce((v,s)=>v+s.reps,0):null)}});
 pts=pts.filter(p=>p.date>=cutoff&&p.date<=data.asOf&&Number.isFinite(p.value));
 $('trend-title').textContent=view==='strength'?'Kraftverlauf':view==='cardio'?'Ausdauerverlauf':'Schlaf & Erholung';$('chart-unit').textContent=metric.unit;
 $('chart-note').textContent=key==='load'?'Erfasste Last pro Einheit, nicht automatisch Gesamtgewicht. 0 kg und fehlende Lasten werden ausgelassen. Unterschiedliche Geräte oder Gewichtskonventionen sind nicht vergleichbar.':key==='reps'?'Summe der erfassten Wiederholungen. Änderungen an Satzanzahl und einseitiger Zählung beeinflussen den Wert.':key==='cardioHr'?'Verschiedene Geräte sind gemeinsam dargestellt. Ein niedrigerer oder höherer Puls allein beweist keine Fitnessänderung.':key==='kg'?'Eine Messung pro Tag (letzter vorhandener Eintrag). Einzelne Schwankungen erlauben keine Aussage zu Fett- oder Muskelveränderungen.':'Gemessene Garmin-Werte. Fehlende Tage bleiben als Lücken sichtbar; keine Diagnose oder Bereitschaftsbewertung.';
 if(!pts.length){$('chart').innerHTML='<div class="empty">Für diese Auswahl fehlen bestätigte Messwerte.</div>';return}
 const width=Math.max(300,$('chart').clientWidth),height=220,left=46,right=22,top=20,bottom=34,min=Math.min(...pts.map(p=>p.value)),max=Math.max(...pts.map(p=>p.value)),pad=Math.max((max-min)*.2,key==='kg'?.3:1),lo=min-pad,hi=max+pad,x=d=>left+(dt(d)-dt(cutoff))/(864e5*(days-1))*(width-left-right),y=v=>height-bottom-(v-lo)/(hi-lo)*(height-top-bottom);
 const grids=Array.from({length:4},(_,i)=>{const v=lo+(hi-lo)*i/3,yy=y(v);return `<line class="chart-grid" x1="${left}" x2="${width-right}" y1="${yy}" y2="${yy}"/><text class="chart-label" x="${left-10}" y="${yy+4}" text-anchor="end">${num(v,1)}</text>`}).join('');
 const lines=pts.slice(1).map((p,i)=>{const prev=pts[i],gap=(dt(p.date)-dt(prev.date))/864e5;return ['sleep','hrv','restingHr'].includes(key)&&gap>1?'':`<path class="chart-line" style="stroke:${metric.color}" d="M${x(prev.date)} ${y(prev.value)} L${x(p.date)} ${y(p.value)}"/>`}).join('');
 const dots=pts.map(p=>`<circle class="chart-dot" style="stroke:${metric.color}" cx="${x(p.date)}" cy="${y(p.value)}" r="4"><title>${short(p.date)}: ${num(p.value,2)} ${metric.unit}</title></circle>`).join('');
 $('chart').innerHTML=`<svg role="img" aria-label="${esc(metric.label)}: ${pts.length} Messwerte, letzter Wert ${num(pts.at(-1).value,2)} ${metric.unit}" viewBox="0 0 ${width} ${height}">${grids}${lines}${dots}<text class="chart-label" x="${left}" y="${height-4}">${short(cutoff)}</text><text class="chart-label" x="${width-right}" y="${height-4}" text-anchor="end">${short(data.asOf)}</text></svg>`;
}
function renderActivities(){const filter=$('activity-filter').value,cutoff=add(data.asOf,-days+1);const acts=data.activities.filter(a=>a.date>=cutoff&&(filter==='all'||kind(a)===filter)).slice().reverse();$('activities').innerHTML=acts.map(a=>`<tr><td>${short(a.date)}</td><td>${esc(a.name.replace(/ ·.*$/,''))}<span class="tag">${kind(a)==='strength'?'KRAFT':'CARDIO'}</span></td><td>${num(a.minutes,1)} min</td><td>${a.avgHr??'—'} bpm</td><td><button class="note-button" data-note="${esc(a.id)}" title="${esc(notes[a.id]||'Notiz hinzufügen')}">${notes[a.id]?'Notiz ansehen':'＋ Notiz'}</button></td></tr>`).join('')||'<tr><td colspan="5">Keine Einheiten im gewählten Zeitraum.</td></tr>';document.querySelectorAll('[data-note]').forEach(b=>b.onclick=()=>{noteId=b.dataset.note;$('note-session').textContent=data.activities.find(a=>a.id===noteId).name;$('note-text').value=notes[noteId]||'';$('note-dialog').showModal()})}
function toast(msg){$('toast').textContent=msg;$('toast').hidden=false;setTimeout(()=>$('toast').hidden=true,3500)}
document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>{view=b.dataset.view;setChartChoices();$('activity-filter').value=view==='strength'?'strength':view==='cardio'?'cardio':'all';render()});$('previous').onclick=()=>{weekStart=add(weekStart,-7);render()};$('next').onclick=()=>{weekStart=add(weekStart,7);render()};document.querySelectorAll('[data-days]').forEach(b=>b.onclick=()=>{days=Number(b.dataset.days);document.querySelectorAll('[data-days]').forEach(x=>x.classList.toggle('selected',x===b));renderChart();renderActivities()});$('chart-metric').onchange=renderChart;$('exercise').onchange=renderChart;$('activity-filter').onchange=renderActivities;
$('refresh').onclick=()=>{$('data-detail').textContent='Geladene Daten bis '+short(data.asOf)+data.asOf.slice(0,4)+'. Letzte Renpho-Messung: '+(data.weights.length?short(data.weights.at(-1).date):'keine')+'.';$('data-dialog').showModal()};$('close-data').onclick=()=>$('data-dialog').close();$('reload-data').onclick=async()=>{try{await load();$('data-dialog').close();toast('Veröffentlichter Datenstand geladen.')}catch{toast('Daten konnten nicht geladen werden.')}};$('close-note').onclick=()=>$('note-dialog').close();$('note-form').onsubmit=e=>{e.preventDefault();notes[noteId]=$('note-text').value.trim();try{localStorage.setItem('momentum-notes',JSON.stringify(notes));$('note-dialog').close();renderActivities();toast('Notiz in diesem Browser gespeichert.')}catch{toast('Browserspeicher nicht verfügbar. Bitte exportieren.')}};
$('export').onclick=()=>{const blob=new Blob([JSON.stringify({...data,notes},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='momentum-'+data.asOf+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};$('import-button').onclick=()=>$('import').click();$('import').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>5e6)throw Error('Datei zu groß');const d=valid(JSON.parse(await f.text()));data=d;weekStart=monday(d.asOf);if(d.notes&&typeof d.notes==='object'){notes=Object.fromEntries(Object.entries(d.notes).filter(([k,v])=>typeof v==='string').map(([k,v])=>[k,v.slice(0,1000)]));try{localStorage.setItem('momentum-notes',JSON.stringify(notes))}catch{}}setChartChoices();render();toast('Daten importiert – für diese Ansicht.')}catch(e){toast(e.message||'Import fehlgeschlagen')}finally{$('import').value=''}};
window.addEventListener('resize',()=>{if(data)renderChart()});
load().catch(()=>{$('freshness').textContent='Daten konnten nicht geladen werden.';toast('Laden fehlgeschlagen. Bitte die Seite neu laden.')});
